export default function Features(){

const features=[
"Passwordless Login",
"Secure Token Authentication",
"Email Based Login",
"Instant Authentication"
]

return(

<section id="features" className="py-24 px-10">

<h2 className="text-4xl text-center font-bold text-gradient mb-16">
Features
</h2>

<div className="grid md:grid-cols-4 gap-6">

{features.map((f,i)=>(
<div key={i} className="glass-card card-hover p-6 text-center">
<h3 className="font-semibold">{f}</h3>
</div>
))}

</div>

</section>

)

}
